package com.ruoyi.framework.audit;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.time.*;import com.alibaba.fastjson2.*;import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.jdbc.core.JdbcTemplate;
@Component public class RuntimeCollector{private final JdbcTemplate jdbc;public RuntimeCollector(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Scheduled(fixedDelay=2000) public void collect(){try{Path root=Path.of("logs");if(!Files.exists(root))return;try(var paths=Files.list(root)){for(Path file:paths.filter(p->p.getFileName().toString().startsWith("runtime")&&(p.toString().endsWith(".jsonl")||p.toString().endsWith(".jsonl.gz"))).sorted().toList())read(file);}}catch(Exception ignored){}}
 private void read(Path file)throws Exception{String name=file.getFileName().toString();if(name.endsWith(".gz")){readGzip(file);return;}long offset=jdbc.queryForList("SELECT file_offset FROM audit_file_cursor WHERE file_name=?",name).stream().mapToLong(r->((Number)r.get("file_offset")).longValue()).findFirst().orElse(0);try(var in=new java.io.RandomAccessFile(file.toFile(),"r")){in.seek(offset>in.length()?0:offset);for(int i=0;i<300;i++){long start=in.getFilePointer();String line=in.readLine();if(line==null)break;JSONObject e;try{e=JSON.parseObject(new String(line.getBytes(StandardCharsets.ISO_8859_1),StandardCharsets.UTF_8));}catch(Exception partial){in.seek(start);break;}jdbc.update("INSERT IGNORE INTO sys_runtime_log(event_id,event_time,level,service,component,event_type,summary,trace_id,exception_class,detail_json) VALUES(?,?,?,?,?,?,?,?,?,?)",e.get("eventId"),LocalDateTime.parse(e.getString("time")),e.get("level"),e.get("service"),e.get("component"),e.get("exceptionClass")!=null?"EXCEPTION":"RUNTIME",e.get("summary"),e.get("traceId"),e.get("exceptionClass"),JSON.toJSONString(Map.of("stack",e.getString("stack")==null?"":e.getString("stack"),"thread",e.getString("thread"))));jdbc.update("INSERT INTO audit_file_cursor(file_name,file_offset) VALUES(?,?) ON DUPLICATE KEY UPDATE file_offset=VALUES(file_offset)",name,in.getFilePointer());}}}
 private void readGzip(Path file)throws Exception{String name=file.getFileName().toString();long offset=jdbc.queryForList("SELECT file_offset FROM audit_file_cursor WHERE file_name=?",name).stream().mapToLong(r->((Number)r.get("file_offset")).longValue()).findFirst().orElse(0);try(var gzip=new java.util.zip.GZIPInputStream(Files.newInputStream(file))){gzip.skipNBytes(offset);try(var reader=new java.io.BufferedReader(new java.io.InputStreamReader(gzip,StandardCharsets.UTF_8))){for(int i=0;i<300;i++){String line=reader.readLine();if(line==null)break;JSONObject e=JSON.parseObject(line);jdbc.update("INSERT IGNORE INTO sys_runtime_log(event_id,event_time,level,service,component,event_type,summary,trace_id,exception_class,detail_json) VALUES(?,?,?,?,?,?,?,?,?,?)",e.get("eventId"),LocalDateTime.parse(e.getString("time")),e.get("level"),e.get("service"),e.get("component"),e.get("exceptionClass")!=null?"EXCEPTION":"RUNTIME",e.get("summary"),e.get("traceId"),e.get("exceptionClass"),JSON.toJSONString(Map.of("stack",e.getString("stack")==null?"":e.getString("stack"))));offset+=line.getBytes(StandardCharsets.UTF_8).length+1;jdbc.update("INSERT INTO audit_file_cursor(file_name,file_offset) VALUES(?,?) ON DUPLICATE KEY UPDATE file_offset=VALUES(file_offset)",name,offset);}}}}

}
